/* Interactive lab viewer. All data comes from window.LAB_DATA, generated by
   lab/build_evidence.py from real service responses. Nothing is hard-coded
   except rendering geometry and the digest of the generated data file. */

(function () {
  "use strict";

  const DATA = window.LAB_DATA;
  const FRAME_DIR = "frames/";
  const CLIP = DATA.clip;
  const FRAME_COUNT = CLIP.frameCount;
  const FRAME_ASSETS = CLIP.frameAssets;
  const DESIGN = CLIP.designScenes;
  const STRIDES = DATA.strides;
  const THRESHOLD = 0.50 - DATA.conditions.sensitivity * 0.30;

  const palette = [
    "#8fd3e8", "#e7c46b", "#6f8fe8", "#84c88f",
    "#d79ac0", "#f08a5d", "#b48ead", "#c0c0c8",
    "#a7c95a", "#7cc8c0",
  ];

  const $ = (id) => document.getElementById(id);
  const el = (tag, cls, text) => {
    const node = document.createElement(tag);
    if (cls) node.className = cls;
    if (text !== undefined) node.textContent = text;
    return node;
  };
  const fmt = (value, digits = 2) =>
    Number(value).toLocaleString("en-US", {
      minimumFractionDigits: digits,
      maximumFractionDigits: digits,
    });
  const shortDigest = (digest, len = 16) =>
    digest ? digest.slice(0, len) + "…" : "—";

  function framePath(index) {
    const asset = FRAME_ASSETS[index];
    if (!asset) return "";
    return FRAME_DIR + asset.png_path;
  }

  function truthScene(index) {
    return DESIGN.find(
      (scene) => scene.start_frame <= index && index < scene.end_frame,
    );
  }

  function sceneForRun(run, frameIndex) {
    const scene = run.record.scenes.find(
      (scene) => scene.start_frame <= frameIndex && frameIndex < scene.end_frame,
    );
    if (!scene) return null;
    const stats = run.metrics.scene_stats.find(
      (item) => item.scene_index === scene.index,
    );
    return { ...scene, truth_indices: stats ? stats.covered_truth_scenes : [] };
  }

  function nearestDetected(run, frameIndex) {
    let best = null;
    let bestDistance = Infinity;
    for (const cut of run.record.cut_frames) {
      const distance = Math.abs(cut - frameIndex);
      if (distance < bestDistance) {
        bestDistance = distance;
        best = cut;
      }
    }
    return { frame: best, distance: bestDistance };
  }

  /* ---------------- tabs ---------------- */

  const tabs = Array.from(document.querySelectorAll(".tab"));
  const panels = Array.from(document.querySelectorAll(".panel"));
  const activated = new Set();

  function showTab(id) {
    tabs.forEach((tab) => tab.classList.toggle("active", tab.dataset.tab === id));
    panels.forEach((panel) => panel.classList.toggle("active", panel.id === id));
    if (!activated.has(id)) {
      activated.add(id);
      const init = TAB_INITS[id];
      if (init) init();
    }
    window.scrollTo({ top: 0, behavior: "instant" });
  }

  tabs.forEach((tab) => {
    tab.addEventListener("click", () => showTab(tab.dataset.tab));
  });

  const TAB_INITS = {};

  /* ---------------- step 1: frame stepping ---------------- */

  let currentFrame = 0;

  function drawFrameStrip(container, selector, current) {
    container.innerHTML = "";
    DESIGN.forEach((scene, index) => {
      const segment = el("div", "strip-seg");
      segment.style.width = `${((scene.end_frame - scene.start_frame) / FRAME_COUNT) * 100}%`;
      segment.style.background = palette[index % palette.length];
      segment.title = `${scene.label} · 帧 ${scene.start_frame}–${scene.end_frame - 1}`;
      if (current >= scene.start_frame && current < scene.end_frame) {
        const cursor = el("div", "cursor");
        cursor.style.left = `${((current - scene.start_frame) / (scene.end_frame - scene.start_frame)) * 100}%`;
        segment.append(cursor);
      }
      segment.addEventListener("click", (event) => {
        const rect = segment.getBoundingClientRect();
        const fraction = Math.min(
          0.999,
          Math.max(0, (event.clientX - rect.left) / Math.max(1, rect.width)),
        );
        const frame =
          scene.start_frame +
          Math.floor(fraction * (scene.end_frame - scene.start_frame));
        selector(frame);
      });
      container.append(segment);
    });
  }

  function renderFrame(index, keepOrigin) {
    currentFrame = index;
    if (!keepOrigin) {
      const holder = $("frame-origin");
      holder.innerHTML = "";
      holder.hidden = true;
    }
    const asset = FRAME_ASSETS[index];
    $("frame-img").src = framePath(index);
    $("frame-slider").value = String(index);
    $("frame-number").textContent = `帧 ${String(index).padStart(3, "0")} / ${FRAME_COUNT - 1}`;
    $("frame-digest").textContent = "源 RGB SHA-256 " + shortDigest(asset.rgb_sha256, 32);
    const scene = truthScene(index);
    const badge = $("frame-scene-label");
    badge.textContent = `设计镜头 ${scene.index} · ${scene.label}`;
    badge.style.borderColor = palette[scene.index % palette.length];
    badge.style.color = palette[scene.index % palette.length];
    drawFrameStrip($("frame-strip"), renderFrame, index);
  }

  function initFrames() {
    const meta = $("clip-meta");
    meta.innerHTML = "";
    const cells = [
      ["剪辑 ID", CLIP.id],
      ["尺寸", `${CLIP.width}×${CLIP.height} @ ${CLIP.fps}fps`],
      ["帧数", String(CLIP.frameCount)],
      ["字节数", fmt(CLIP.byteSize, 0)],
      ["剪辑 SHA-256", shortDigest(CLIP.sha256, 24)],
      ["设计镜头", String(DESIGN.length)],
    ];
    cells.forEach(([k, v]) => {
      const cell = el("div", "meta-cell");
      cell.append(el("span", "k", k), el("span", "v", v));
      meta.append(cell);
    });

    const legend = $("design-legend");
    legend.innerHTML = "";
    DESIGN.forEach((scene, index) => {
      const swatch = el("div", "legend-swatch");
      const label = el("div", "lbl");
      const dot = el("span", "dot");
      dot.style.background = palette[index % palette.length];
      label.append(dot, el("span", "", scene.label));
      swatch.append(label, el("div", "len", `${scene.length} 帧 · ${scene.start_frame}–${scene.end_frame - 1}`));
      swatch.addEventListener("click", () => renderFrame(scene.start_frame));
      legend.append(swatch);
    });

    $("frame-slider").max = String(FRAME_COUNT - 1);
    $("frame-slider").addEventListener("input", (event) =>
      renderFrame(Number(event.target.value)),
    );
    $("frame-prev").addEventListener("click", () =>
      renderFrame((currentFrame - 1 + FRAME_COUNT) % FRAME_COUNT),
    );
    $("frame-next").addEventListener("click", () =>
      renderFrame((currentFrame + 1) % FRAME_COUNT),
    );
    window.addEventListener("keydown", (event) => {
      if (!$("step-frames").classList.contains("active")) return;
      if (event.key === "ArrowLeft") {
        event.preventDefault();
        renderFrame((currentFrame - 1 + FRAME_COUNT) % FRAME_COUNT);
      } else if (event.key === "ArrowRight") {
        event.preventDefault();
        renderFrame((currentFrame + 1) % FRAME_COUNT);
      }
    });
    renderFrame(0);
  }
  TAB_INITS["step-frames"] = initFrames;

  /* ---------------- step 2: scene segmentation ---------------- */

  let sceneStride = 1;
  let sceneFrame = 0;

  function drawTruthStrip(container, current, detected, showLabels, segments) {
    container.innerHTML = "";
    const strip = el("div", "truth-seg");
    segments.forEach((scene, index) => {
      const cell = el("div", "seg-cell");
      cell.style.width = `${((scene.end_frame - scene.start_frame) / FRAME_COUNT) * 100}%`;
      cell.style.background = palette[index % palette.length];
      if (current >= scene.start_frame && current < scene.end_frame) {
        cell.style.outline = "2px solid #fff";
        cell.style.zIndex = "2";
      }
      cell.title = `${scene.label || "场景 " + index} · ${scene.start_frame}–${scene.end_frame - 1}`;
      cell.append(el("label", "", showLabels ? scene.label : `#${index}`));
      strip.append(cell);
    });
    container.append(strip);

    const markers = el("div", "marker-strip");
    CLIP.truthCuts.forEach((cut) => {
      const tick = el("div", "marker-tick");
      tick.style.left = `${(cut / FRAME_COUNT) * 100}%`;
      tick.title = `真实切点 ${cut}`;
      markers.append(tick);
    });
    (detected || []).forEach((cut) => {
      const tick = el("div", "marker-tick detected");
      tick.style.left = `${(cut / FRAME_COUNT) * 100}%`;
      tick.title = `服务接受的分界 ${cut}`;
      markers.append(tick);
    });
    if (current !== null) {
      const cursor = el("div", "marker-tick");
      cursor.style.left = `${(current / FRAME_COUNT) * 100}%`;
      cursor.style.background = "#fff";
      cursor.style.width = "2px";
      cursor.style.height = "22px";
      markers.append(cursor);
    }
    container.append(markers);
    const hint = el(
      "div",
      "muted small",
      detected && detected.length
        ? "橙线 = 设计真实切点；红线 = 服务实际接受的分界；白线 = 当前帧。"
        : "橙线 = 设计真实切点；白线 = 当前帧。",
    );
    hint.style.marginTop = "22px";
    container.append(hint);
  }

  function renderSceneFrame(index) {
    sceneFrame = index;
    const run = STRIDES.find((item) => item.stride === sceneStride);
    $("scene-frame-img").src = framePath(index);
    $("scene-slider").value = String(index);
    const truth = truthScene(index);
    const scene = sceneForRun(run, index);
    if (!scene) {
      $("scene-detail").textContent = "该帧不属于任何服务场景（不应发生）。";
      return;
    }
    const nearest = nearestDetected(run, index);
    $("scene-frame-caption").textContent =
      `帧 ${index} · 设计镜头 ${truth.index}「${truth.label}」 · 服务场景 ${scene.index}（${scene.start_frame}–${scene.end_frame - 1}）`;
    $("scene-detail").innerHTML = "";
    const detail = $("scene-detail");
    const rows = [
      [
        "服务场景",
        `#${scene.index} · 帧 ${scene.start_frame}–${scene.end_frame - 1} · 代表帧 ${scene.representative_frame}`,
      ],
      [
        "该场景覆盖的设计镜头",
        scene.truth_indices
          .map(
            (index) =>
              `${index}「${DESIGN[index].label}」(第 ${DESIGN[index].start_frame}–${DESIGN[index].end_frame - 1} 帧)`,
          )
          .join("；") +
          (scene.truth_indices.length > 1 ? " —— 多个真实镜头被合并" : ""),
      ],
      [
        "最近的已接受分界",
        nearest.frame === null
          ? "无分界"
          : `帧 ${nearest.frame}（距当前 ${nearest.distance} 帧）`,
      ],
      ["指纹统计", `平均亮度 ${fmt(scene.mean_luma, 2)} · 对比度 ${fmt(scene.contrast, 2)}`],
    ];
    rows.forEach(([k, v]) => {
      const row = el("div", "row");
      row.style.marginBottom = "6px";
      row.append(el("span", "mono", k + "："), document.createTextNode(v));
      detail.append(row);
    });
    const truthLine = el(
      "div",
      "muted small",
      scene.truth_indices.length > 1
        ? "这一格服务场景合并了多个设计真实镜头，联系表只能为它显示一个代表帧。"
        : "服务场景与设计真实镜头一一对应。",
    );
    truthLine.style.marginTop = "8px";
    detail.append(truthLine);
    drawTruthStrip($("truth-segments"), index, [], true, DESIGN);
    drawTruthStrip(
      $("scene-segments"),
      index,
      run.record.cut_frames,
      false,
      run.record.scenes.map((scene) => ({
        ...scene,
        label: `场景 ${scene.index}`,
      })),
    );
    renderSceneStats(run);
    renderDistanceTable(run, scene);
  }

  function renderSceneStats(run) {
    const container = $("scene-stats");
    container.innerHTML = "";
    const metrics = run.metrics;
    const cards = [
      [
        "服务场景数",
        String(metrics.scene_count),
        DESIGN.length > metrics.scene_count ? "bad" : "good",
        `设计真实镜头 ${DESIGN.length}`,
      ],
      [
        "漏掉的真实切点",
        String(metrics.missed_truth_cuts.length),
        metrics.missed_truth_cuts.length ? "bad" : "good",
        metrics.missed_truth_cuts.length
          ? metrics.missed_truth_cuts.map((c) => `帧${c}`).join(" ")
          : "全部覆盖",
      ],
      [
        "被合并的真实镜头",
        String(metrics.scenes_spanning_multiple_truth_shots),
        metrics.scenes_spanning_multiple_truth_shots ? "bad" : "good",
        "服务场景覆盖多个真实镜头",
      ],
      [
        "分界最大偏移",
        String(metrics.max_abs_offset_frames),
        metrics.max_abs_offset_frames > 1 ? "bad" : "good",
        "帧；容差 = 采样步长",
      ],
    ];
    cards.forEach(([k, v, cls, sub]) => {
      const card = el("div", "stat-card " + cls);
      const value = el("div", "v", String(v));
      value.append(el("small", "", " " + sub));
      card.append(el("div", "k", k), value);
      container.append(card);
    });
  }

  function renderDistanceTable(run, scene) {
    const table = $("distance-table");
    table.innerHTML = "";
    const head = el("thead");
    const headRow = el("tr");
    ["采样对", "距离", "阈值判定", "是否跨越设计真实切点"].forEach((label) => {
      headRow.append(el("th", "", label));
    });
    head.append(headRow);
    table.append(head);
    const body = el("tbody");
    const active = new Set(
      scene
        ? run.record.sampled_frames.filter(
            (frame) => frame >= scene.start_frame && frame < scene.end_frame,
          )
        : [],
    );
    let rows = 0;
    run.scores.boundary_pairs.forEach((pair) => {
      const row = el("tr");
      const insideScene =
        active.has(pair.from_frame) || active.has(pair.to_frame);
      if (!insideScene && scene) return;
      rows += 1;
      if (pair.distance < THRESHOLD && pair.spans_truth_cut) row.classList.add("bad");
      const cells = [
        `${pair.from_frame} → ${pair.to_frame}`,
        fmt(pair.distance, 6),
        pair.distance >= THRESHOLD ? "≥ 阈值" : "< 阈值",
        pair.spans_truth_cut ? "是（采样跨过真实切点）" : "否",
      ];
      cells.forEach((value, index) => {
        const cell = el("td", index === 0 || index === 1 ? "mono" : "", value);
        row.append(cell);
      });
      body.append(row);
    });
    if (rows === 0) {
      const row = el("tr");
      const cell = el("td", "", "该场景没有相邻采样对（采样步长大于场景长度）。");
      cell.colSpan = 4;
      row.append(cell);
      body.append(row);
    }
    table.append(body);
  }

  function initScenes() {
    $("threshold-line").textContent =
      `= 0.50 − 0.30 × ${DATA.conditions.sensitivity} = ${THRESHOLD.toFixed(3)}`;
    const select = $("scene-stride");
    STRIDES.forEach((run) => {
      const option = el(
        "option",
        "",
        `步长 ${run.stride} · ${run.label}（${run.record.scenes.length} 场景 / ${run.metrics.missed_truth_cuts.length} 漏检）`,
      );
      option.value = String(run.stride);
      select.append(option);
    });
    select.value = String(sceneStride);
    select.addEventListener("change", (event) => {
      sceneStride = Number(event.target.value);
      renderSceneFrame(Math.min(sceneFrame, FRAME_COUNT - 1));
    });
    $("scene-slider").max = String(FRAME_COUNT - 1);
    $("scene-slider").addEventListener("input", (event) =>
      renderSceneFrame(Number(event.target.value)),
    );
    $("scene-prev").addEventListener("click", () =>
      renderSceneFrame((sceneFrame - 1 + FRAME_COUNT) % FRAME_COUNT),
    );
    $("scene-next").addEventListener("click", () =>
      renderSceneFrame((sceneFrame + 1) % FRAME_COUNT),
    );
    $("scene-jump-cut").addEventListener("click", () => {
      const run = STRIDES.find((item) => item.stride === sceneStride);
      const nearest = nearestDetected(run, sceneFrame);
      if (nearest.frame !== null) renderSceneFrame(nearest.frame);
    });
    renderSceneFrame(0);
  }
  TAB_INITS["step-scenes"] = initScenes;

  /* ---------------- step 3: contact sheet <-> frames ---------------- */

  let sheetStride = 1;
  let sheetSceneIndex = 0;
  let sheetImage = null;
  let hoveredTileIndex = -1;
  let sheetHovering = false;

  function renderSheetTiles() {
    const run = STRIDES.find((item) => item.stride === sheetStride);
    const sheet = run.sheet;
    $("sheet-frame-caption").textContent = "";
    $("sheet-proof").innerHTML = "";
    $("sheet-meta").innerHTML = "";

    const metaCells = [
      ["联系表 ID", sheet.sheetId],
      ["图像尺寸", `${sheet.imageWidth}×${sheet.imageHeight}`],
      ["格数 / 场景", `${sheet.tiles.length} / ${run.record.scenes.length}`],
      ["合成耗时", `${fmt(sheet.elapsedMs, 1)} ms`],
      ["产物 PPM SHA-256", shortDigest(sheet.artifactDigest, 24)],
      ["显示 PNG SHA-256", shortDigest(sheet.artifactPngSha256, 24)],
    ];
    metaCells.forEach(([k, v]) => {
      const cell = el("div", "meta-cell");
      cell.append(el("span", "k", k), el("span", "v", v));
      $("sheet-meta").append(cell);
    });

    const table = $("tile-table");
    table.innerHTML = "";
    const head = el("thead");
    const headRow = el("tr");
    ["格", "场景", "引用的源帧", "区域", "检查"].forEach((label) =>
      headRow.append(el("th", "", label)),
    );
    head.append(headRow);
    table.append(head);
    const body = el("tbody");
    sheet.tiles.forEach((tile) => {
      const proof = sheet.proofs.find(
        (item) => item.tile_index === tile.tile_index,
      );
      const row = el("tr");
      row.dataset.tileIndex = String(tile.tile_index);
      if (proof && !proof.tile_matches_resample) row.classList.add("bad");
      if (tile.tile_index === sheetSceneIndex) {
        row.style.background = "rgba(110,193,228,0.10)";
      }
      const cells = [
        `#${tile.tile_index}`,
        String(tile.scene_index),
        String(tile.source_frame),
        `${tile.left},${tile.top} ${tile.width}×${tile.height}`,
        proof && proof.tile_matches_resample ? "逐像素一致" : "不一致",
      ];
      cells.forEach((value, index) => {
        const cell = el(
          "td",
          index === 1 || index === 2 ? "mono" : "",
          value,
        );
        row.append(cell);
      });
      row.addEventListener("click", () => gotoFrameFromTile(run, tile));
      body.append(row);
    });
    table.append(body);

    const returnBox = $("sheet-return");
    returnBox.hidden = true;
    returnBox.innerHTML = "";
    sheetImage = null;
    const canvas = $("sheet-canvas");
    const context = canvas.getContext("2d");
    canvas.width = sheet.imageWidth;
    canvas.height = sheet.imageHeight;
    const image = new Image();
    image.onload = () => {
      sheetImage = image;
      context.drawImage(image, 0, 0);
      drawSheetOverlay(run);
      renderSheetFrame(run, sheetSceneIndex);
    };
    image.src = FRAME_DIR + sheet.imagePath;
    canvas.onmousemove = (event) => {
      const rect = canvas.getBoundingClientRect();
      const x = ((event.clientX - rect.left) / rect.width) * canvas.width;
      const y = ((event.clientY - rect.top) / rect.height) * canvas.height;
      hoverSheetTile(run, x, y);
    };
    canvas.onmouseleave = () => {
      hoveredTileIndex = -1;
      drawSheetOverlay(run);
      renderSheetFrame(run, sheetSceneIndex);
    };
    canvas.onclick = (event) => {
      const rect = canvas.getBoundingClientRect();
      const x = ((event.clientX - rect.left) / rect.width) * canvas.width;
      const y = ((event.clientY - rect.top) / rect.height) * canvas.height;
      const tile = sheet.tiles.find(
        (item) =>
          x >= item.left && x < item.left + item.width &&
          y >= item.top && y < item.top + item.height,
      );
      if (tile) gotoFrameFromTile(run, tile);
    };
    for (const row of Array.from(table.querySelectorAll("tbody tr"))) {
      row.addEventListener("mouseenter", () => {
        const tileIndex = Number(row.dataset.tileIndex);
        const tile = sheet.tiles.find((item) => item.tile_index === tileIndex);
        if (tile) {
          hoveredTileIndex = tileIndex;
          highlightHoveredTile(tile);
          renderSheetFrame(run, tileIndex);
        }
      });
    }
  }

  function highlightHoveredTile(tile) {
    const canvas = $("sheet-canvas");
    const context = canvas.getContext("2d");
    if (sheetImage) context.drawImage(sheetImage, 0, 0);
    context.strokeStyle = "#f0b86e";
    context.lineWidth = 2;
    context.strokeRect(tile.left, tile.top, tile.width, tile.height);
  }

  function drawSheetOverlay(run) {
    const canvas = $("sheet-canvas");
    const context = canvas.getContext("2d");
    const sheet = run.sheet;
    const tile = sheet.tiles.find((item) => item.tile_index === sheetSceneIndex);
    if (!sheetImage || !tile) return;
    context.drawImage(sheetImage, 0, 0);
    context.strokeStyle = "#6ec1e4";
    context.lineWidth = 3;
    context.strokeRect(tile.left, tile.top, tile.width, tile.height);
    context.fillStyle = "rgba(110,193,228,0.16)";
    context.fillRect(tile.left, tile.top, tile.width, tile.height);
  }

  function hoverSheetTile(run, x, y) {
    const tile = run.sheet.tiles.find(
      (item) =>
        x >= item.left && x < item.left + item.width &&
        y >= item.top && y < item.top + item.height,
    );
    if (!tile) {
      hoveredTileIndex = -1;
      return;
    }
    if (tile.tile_index === hoveredTileIndex) return;
    hoveredTileIndex = tile.tile_index;
    highlightHoveredTile(tile);
    renderSheetFrame(run, tile.tile_index);
  }


  function renderSheetFrame(run, tileIndex) {
    const tile = run.sheet.tiles.find((item) => item.tile_index === tileIndex);
    if (!tile) return;
    const proof = run.sheet.proofs.find(
      (item) => item.tile_index === tile.tile_index,
    );
    $("sheet-frame-img").src = framePath(tile.source_frame);
    $("sheet-frame-caption").textContent =
      `联系表格 #${tile.tile_index} → 原帧 ${tile.source_frame}`;
    const box = $("sheet-proof");
    box.innerHTML = "";
    const rows = [
      ["格位置", `${tile.left},${tile.top} · ${tile.width}×${tile.height}`],
      ["该格引用的源帧", String(tile.source_frame)],
      ["源帧 RGB SHA-256", (FRAME_ASSETS[tile.source_frame] || {}).rgb_sha256 || "—"],
      ["格的像素 SHA-256", tile.rgb_sha256],
      [
        "PPM 像素 SHA-256",
        run.sheet.artifactPixelsSha256 || "—",
      ],
      [
        "最近邻缩放后逐像素校验",
        proof && proof.tile_matches_resample
          ? "通过：格像素与源帧最近邻缩放后的字节完全相同"
          : "未通过",
      ],
    ];
    rows.forEach(([k, v]) => {
      const row = el("div", "row");
      row.style.marginBottom = "7px";
      row.append(el("span", "mono", k + "："));
      const value = el("span", "mono small", v);
      value.style.wordBreak = "break-all";
      row.append(value);
      box.append(row);
    });

    const returnBox = $("sheet-return");
    returnBox.hidden = false;
    returnBox.innerHTML = "";
    const button = el(
      "button",
      "",
      `↳ 在第 1 步打开原帧 ${tile.source_frame}，再回到本联系表`,
    );
    button.addEventListener("click", () => gotoFrameFromTile(run, tile));
    returnBox.append(button);
  }

  function gotoFrameWithReturn(frameIndex, description, returnLabel, returnAction) {
    showTab("step-frames");
    renderFrame(frameIndex, true);
    const holder = $("frame-origin");
    holder.innerHTML = "";
    holder.hidden = false;
    const button = el("button", "", returnLabel);
    button.addEventListener("click", returnAction);
    const hint = el("span", "muted small", description);
    hint.style.marginLeft = "10px";
    holder.append(button, hint);
  }

  function gotoFrameFromTile(run, tile) {
    gotoFrameWithReturn(
      tile.source_frame,
      `当前显示的是联系表格 #${tile.tile_index} 实际引用的第 ${tile.source_frame} 帧。`,
      `↩ 回到联系表（步长 ${run.stride}，格 #${tile.tile_index}，源帧 ${tile.source_frame}）`,
      () => {
        showTab("step-sheet");
        sheetStride = run.stride;
        sheetSceneIndex = tile.tile_index;
        $("sheet-stride").value = String(run.stride);
        renderSheetTiles();
        renderSheetFrame(run, tile.tile_index);
      },
    );
  }

  function initSheet() {
    const select = $("sheet-stride");
    STRIDES.forEach((run) => {
      const option = el(
        "option",
        "",
        `步长 ${run.stride} · ${run.record.scenes.length} 个场景 / ${run.sheet.tiles.length} 格`,
      );
      option.value = String(run.stride);
      select.append(option);
    });
    select.value = String(sheetStride);
    select.addEventListener("change", (event) => {
      sheetStride = Number(event.target.value);
      sheetSceneIndex = 0;
      renderSheetTiles();
    });
    renderSheetTiles();
  }
  TAB_INITS["step-sheet"] = initSheet;

  /* ---------------- step 4: speed / quality tradeoff ---------------- */

  function initTradeoff() {
    // Idempotent: tabs can be revisited; rebuild from data every time.
    const cards = $("tradeoff-cards");
    cards.innerHTML = "";
    STRIDES.forEach((run) => {
      const metrics = run.metrics;
      const card = el("div", "card");
      card.append(
        el("h3", "", `步长 ${run.stride}`),
        el("div", "sub", run.label),
      );
      const big = el("div", "big");
      big.append(
        document.createTextNode(fmt(run.productionElapsedMs, 0)),
        el("small", "", " ms"),
      );
      card.append(big);
      const detail = el(
        "div",
        "detail",
        `${run.sampleCount} 帧被采样 · ${metrics.scene_count} 个场景 · ` +
          `漏检 ${metrics.missed_truth_cuts.length} 个真实切点 · ` +
          `3 次中位`,
      );
      card.append(detail);
      const flag = el(
        "div",
        "flag " + (metrics.missed_truth_cuts.length > 0 ? "bad" : "ok"),
        `真实切点覆盖 ${metrics.matched_within_tolerance} / ${CLIP.truthCuts.length}`,
      );
      card.append(flag);
      cards.append(card);
    });

    drawBars(
      $("speed-chart"),
      STRIDES.map((run) => ({
        name: `步长 ${run.stride}`,
        value: run.productionElapsedMs,
        text: `${fmt(run.productionElapsedMs, 1)} ms`,
      })),
    );
    drawBars(
      $("quality-chart"),
      STRIDES.map((run) => {
        const missed = run.metrics.missed_truth_cuts.length;
        return {
          name: `步长 ${run.stride}`,
          value: CLIP.truthCuts.length - missed,
          max: CLIP.truthCuts.length,
          text: `${CLIP.truthCuts.length - missed} / ${CLIP.truthCuts.length} 个真实切点被覆盖`,
          alt: missed > 0,
        };
      }),
      "max",
    );

    const table = $("tradeoff-table");
    table.innerHTML = "";
    const head = el("thead");
    const headRow = el("tr");
    [
      "采样设置",
      "采样帧数",
      "服务耗时",
      "场景数",
      "覆盖真实切点",
      "漏检真实切点",
      "分界最大偏移",
      "代表帧错误",
    ].forEach((label) => headRow.append(el("th", "", label)));
    head.append(headRow);
    table.append(head);
    const body = el("tbody");
    STRIDES.forEach((run) => {
      const row = el("tr");
      const metrics = run.metrics;
      if (metrics.missed_truth_cuts.length) row.classList.add("bad");
      const values = [
        `步长 ${run.stride} · ${run.label}`,
        String(run.sampleCount),
        `${fmt(run.productionElapsedMs, 1)} ms`,
        String(metrics.scene_count),
        `${metrics.matched_within_tolerance} / ${CLIP.truthCuts.length}`,
        metrics.missed_truth_cuts.length
          ? metrics.missed_truth_cuts
              .map((cut) => {
                const detail = (metrics.missed_details || []).find(
                  (item) => item.truth_frame === cut,
                );
                const label = detail ? detail.label : "";
                const reason = detail
                  ? detail.reason === "short_shot_skipped_by_stride"
                    ? "短镜头被跳过"
                    : detail.reason === "below_threshold_at_every_stride"
                      ? "阈值以下（所有步长均漏）"
                      : "该步长漏检"
                  : "";
                return `帧${cut}「${label}」${reason}`;
              })
              .join("；")
          : "无",
        `${metrics.max_abs_offset_frames} 帧`,
        String(metrics.representative_frame_mismatches),
      ];
      values.forEach((value, index) => {
        row.append(el("td", index === 0 ? "" : "mono", value));
      });
      body.append(row);
    });
    table.append(body);

    const missedNote = el("p", "small muted");
    const allStrideMissed = STRIDES.every((run) =>
      (run.metrics.missed_details || []).some(
        (item) => item.reason === "below_threshold_at_every_stride",
      ),
    );
    missedNote.textContent = allStrideMissed
      ? "低对比硬切（帧 102、142）在所有采样步长下都低于固定阈值 0.335，属于检测器边界；步长 4 另外完全跳过了两帧短镜头（帧 110、112）。"
      : "漏检原因见上表。";
    missedNote.id = "tradeoff-note";
    missedNote.style.marginTop = "10px";
    table.insertAdjacentElement("afterend", missedNote);

    const detail = $("tradeoff-detail");
    detail.innerHTML = "";
    const timingTitle = el(
      "p",
      "small muted",
      "每个设置独立提交 3 次检验请求（ID 不同），取 3 次耗时中位数；联系表始终由第 1 次记录合成。",
    );
    detail.append(timingTitle);
    STRIDES.forEach((run) => {
      const point = el("p", "small muted");
      point.textContent =
        `步长 ${run.stride}：扫描解码 ${fmt(run.scanMs, 1)} ms，` +
        `单帧驻留峰值 ${run.peakFrames}，服务实测驻留峰值 ` +
        `${run.residencyPeak}；3 次耗时 ${run.timingSamplesMs.map((v) => fmt(v, 1)).join(" / ")} ms；` +
        `场景内最大采样对距离 ${fmt(run.scores.max_distance_inside_shots, 5)}。`;
      detail.append(point);
    });
  }
  TAB_INITS["step-tradeoff"] = initTradeoff;

  function drawBars(container, rows, mode) {
    container.innerHTML = "";
    const maxValue = Math.max(...rows.map((row) => row.value), 0.001);
    const scaleMax = mode === "max" ? rows[0].max : maxValue;
    rows.forEach((row) => {
      const rowEl = el("div", "bar-row");
      const name = el("div", "name", row.name);
      const track = el("div", "bar-track");
      const fill = el("div", "bar-fill" + (row.alt ? " bad" : ""));
      fill.style.width = `${Math.max(2, (row.value / scaleMax) * 100)}%`;
      track.append(fill);
      const value = el("div", "value", row.text);
      rowEl.append(name, track, value);
      container.append(rowEl);
    });
  }

  /* ---------------- step 5: counterexample ---------------- */

  function initCounter() {
    const counter = DATA.counterexample;
    const frames = counter.frameAssets;
    $("counter-left").src = FRAME_DIR + frames[3].png_path;
    $("counter-right").src = FRAME_DIR + frames[4].png_path;
    $("counter-left").onclick = () =>
      gotoFrameWithReturn(
        3,
        "帧 3：旋转前的最后一帧。",
        "↩ 回到反例",
        () => showTab("step-counter"),
      );
    $("counter-right").onclick = () =>
      gotoFrameWithReturn(
        4,
        "帧 4：帧 0 的精确 180° 旋转，统计量不变。",
        "↩ 回到反例",
        () => showTab("step-counter"),
      );
    const pair = counter.pairs.find(
      (item) => item.left_frame === 3 && item.right_frame === 4,
    );
    const fields = counter.fields;
    const stats = $("counter-stats");
    stats.innerHTML = "";
    const cards = [
      ["统计距离（帧 3 → 帧 4）", fmt(pair.distance, 9), "good", "指纹完全相同"],
      ["像素是否不同", pair.pixels_differ ? "不同" : "相同", "bad", "每像素都变了"],
      ["平均亮度 帧 3", fmt(fields.left.mean_luma, 6), "", ""],
      ["平均亮度 帧 4", fmt(fields.right.mean_luma, 6), "", ""],
      ["对比度 帧 3", fmt(fields.left.contrast, 6), "", ""],
      ["对比度 帧 4", fmt(fields.right.contrast, 6), "", ""],
      ["服务判定", `cut_frames = [${counter.inspection.record.cut_frames.join(", ")}]`, "bad", "整段被视为单一场景"],
      ["逐帧验证峰值", String(counter.inspection.boundedScanPeakFrames), "", "源 RGB 驻留"],
    ];
    cards.forEach(([k, v, cls, sub]) => {
      const card = el("div", "stat-card " + cls);
      card.append(el("div", "k", k), el("div", "v", v));
      if (sub) card.append(el("div", "small muted", sub));
      stats.append(card);
    });

    const table = $("counter-pairs");
    table.innerHTML = "";
    const head = el("thead");
    const headRow = el("tr");
    ["左边帧", "右边帧", "指纹距离", "像素是否不同"].forEach((label) =>
      headRow.append(el("th", "", label)),
    );
    head.append(headRow);
    table.append(head);
    const body = el("tbody");
    counter.pairs.forEach((item) => {
      const row = el("tr");
      const values = [
        String(item.left_frame),
        String(item.right_frame),
        fmt(item.distance, 9),
        item.pixels_differ === undefined ? "—" : item.pixels_differ ? "不同" : "相同",
      ];
      values.forEach((value, index) => {
        row.append(el("td", index >= 2 ? "mono" : "", value));
      });
      body.append(row);
    });
    table.append(body);

    const sheetTiles = counter.inspection.sheet.tiles;
    const counterNote = el(
      "p",
      "small muted",
        `联系表只有 ${sheetTiles.length} 格：场景 0 的代表帧是第 ${sheetTiles[0] ? sheetTiles[0].source_frame : "?"} 帧，` +
      "服务把翻转后的帧 4–7 也当作同一场景，因此看不到翻转。",
    );
    counterNote.style.gridColumn = "1 / -1";
    $("counter-stats").append(counterNote);

    const linkRow = el("div", "return-link");
    linkRow.style.gridColumn = "1 / -1";
    const openLeft = el("button", "", "在第 1 步打开帧 3（左图来源）");
    openLeft.addEventListener("click", () =>
      gotoFrameWithReturn(
        3,
        "左图：帧 3，统计距离 0.0 的另一侧是帧 4。",
        "↩ 回到反例",
        () => showTab("step-counter"),
      ),
    );
    const openRight = el("button", "", "在第 1 步打开帧 4（右图来源）");
    openRight.style.marginLeft = "10px";
    openRight.addEventListener("click", () =>
      gotoFrameWithReturn(
        4,
        "右图：帧 4，是帧 0 的精确 180° 旋转，统计量没有变化。",
        "↩ 回到反例",
        () => showTab("step-counter"),
      ),
    );
    linkRow.append(openLeft, openRight);
    $("counter-stats").append(linkRow);
  }
  TAB_INITS["step-counter"] = initCounter;

  /* ---------------- step 6: interruption ---------------- */

  function initInterrupt() {
    const info = DATA.interruption;
    $("reuse-table").innerHTML = "";
    const grid = $("interrupt-grid");
    grid.innerHTML = "";
    const attempt = info.attempt;
    const retry = info.retry_same_id;
    const reuse = info.reuse;
    const steps = [
      [
        "01",
        "客户端中途中断",
        `请求已发送，记录在 ${attempt.client_close.record_visible_at_ms} ms 时可见，` +
          `随后客户端在 ${attempt.client_close.closed_after_ms} ms 关闭连接。`,
        "客户端断开",
      ],
      [
        "02",
        "服务端仍完成并提交",
        `任务继续运行，轮询 ${attempt.poll_requests} 次后看到终态；` +
          `提交状态 ${attempt.committed_state}，分界 ${attempt.committed_cut_frames.join(", ")}。`,
        "indexed / committed",
      ],
      [
        "03",
        "同一 ID 重试被拒绝",
        `第二次提交返回 HTTP ${retry.status}，错误码 ${retry.error_code}。` +
          "服务不允许覆盖已提交记录，也不接受部分输出拼接。",
        `${retry.status} ${retry.error_code}`,
      ],
      [
        "04",
        "复用已提交结果",
        `从已存 AVI 重新解码 ${reuse.verified_frames.length} 个被采样帧，` +
          `逐帧摘要与指纹摘要均记录；复用判定与提交记录一致：${reuse.reuse_verdict_matches_committed_record ? "是" : "否"}。`,
        "逐帧验证",
      ],
      [
        "05",
        "由已提交记录合成联系表",
        `联系表 ${reuse.sheet_state}，${reuse.sheet_tiles} 格；产物摘要与记录摘要一致：` +
          `${reuse.artifact_matches_record ? "是" : "否"}。`,
        `HTTP ${reuse.sheet_status}`,
      ],
    ];
    steps.forEach(([n, title, text, state]) => {
      const card = el("div", "step-card");
      card.append(
        el("div", "n", "步骤 " + n),
        el("h3", "", title),
        el("p", "", text),
        el("span", "state", state),
      );
      grid.append(card);
    });

    const table = $("reuse-table");
    table.innerHTML = "";
    const head = el("thead");
    const headRow = el("tr");
    ["帧序号", "重新解码的源 RGB SHA-256", "指纹摘要 SHA-256"].forEach((label) =>
      headRow.append(el("th", "", label)),
    );
    head.append(headRow);
    table.append(head);
    const body = el("tbody");
    reuse.verified_frames.slice(0, 12).forEach((item) => {
      const row = el("tr");
      [String(item.index), shortDigest(item.frame_digest, 28), shortDigest(item.fingerprint_digest, 28)].forEach(
        (value, index) => row.append(el("td", "mono", value)),
      );
      body.append(row);
    });
    table.append(body);
    const note = el(
      "p",
      "small muted",
    );
    note.textContent =
      `表中展示前 12 个被采样帧；完整 ${reuse.verified_frames.length} 条在 evidence.json 的 interruption.reuse.verified_frames。` +
      `已存剪辑 SHA-256 与生成清单一致：${reuse.clip_digest_matches_stored_media ? "是" : "否"}。`;
    note.style.marginTop = "8px";
    $("reuse-table").insertAdjacentElement("afterend", note);

    const requestBox = $("interrupt-requests");
    requestBox.innerHTML = "";
    const requests = info.requests || [];
    if (requests.length) {
      const title = el("h3", "", "复用路径的 HTTP 响应");
      requestBox.append(title);
      const list = el("table", "data-table");
      const head = el("thead");
      const headRow = el("tr");
      ["方法", "路径", "状态", "字节", "响应 SHA-256"].forEach((label) =>
        headRow.append(el("th", "", label)),
      );
      head.append(headRow);
      list.append(head);
      const body = el("tbody");
      requests.forEach((item) => {
        const row = el("tr");
        [
          item.method,
          item.path,
          String(item.status),
          String(item.body_bytes),
          shortDigest(item.body_sha256, 28),
        ].forEach((value, index) => row.append(el("td", index === 0 ? "mono" : "mono small", value)));
        body.append(row);
      });
      list.append(body);
      requestBox.append(list);
    }
  }
  TAB_INITS["step-interrupt"] = initInterrupt;

  /* ---------------- step 7: audit ---------------- */

  function initAudit() {
    const checks = DATA.crossChecks;
    const grid = $("audit-checks");
    grid.innerHTML = "";
    Object.entries(checks).forEach(([key, value]) => {
      const card = el("div", "card");
      card.append(el("h3", "", key.replace(/_/g, " ")));
      const numeric = typeof value === "number";
      const flag = el(
        "div",
        "flag " + (numeric ? "ok" : value ? "ok" : "bad"),
        numeric ? `数值 ${value}` : value ? "PASS" : "FAIL",
      );
      card.append(flag);
      grid.append(card);
    });

    const conditions = DATA.conditions;
    const box = $("audit-conditions");
    box.innerHTML = "";
    const rows = [
      ["灵敏度", String(conditions.sensitivity)],
      ["最小场景帧数", String(conditions.min_scene_frames)],
      ["比较的采样步长", conditions.strides.join(", ")],
      ["单任务源 RGB 驻留上限", `${conditions.source_rgb_residency_limit} 帧`],
      [
        "本次实验实测最大驻留",
        `${DATA.crossChecks.max_observed_source_rgb_frames} 帧（含生产请求运行时探测）`,
      ],
      ["指纹阈值", `0.50 − 0.30 × ${conditions.sensitivity} = ${fmt(THRESHOLD, 3)}`],
      ["驻留说明", conditions.frame_retention],
      ["最小场景规则", conditions.min_scene_guard_note],
      ["质量定义", conditions.quality_definition],
      ["已知局限", (conditions.known_limitations || []).join(" ")],
      [
        "耗时口径",
        "每个设置 3 次独立请求的中位数；联系表由第 1 次记录合成。" +
          (checks.median_speed_is_monotonic
            ? "3 次中位数随步长增大而下降（由构建脚本断言）。"
            : "3 次中位数未随步长单调下降。"),
      ],
    ];
    rows.forEach(([k, v]) => {
      const row = el("div", "row");
      row.append(el("strong", "", k + "："), document.createTextNode(v));
      box.append(row);
    });

    const table = $("request-table");
    table.innerHTML = "";
    const head = el("thead");
    const headRow = el("tr");
    ["#", "方法", "路径", "状态", "耗时", "字节", "SHA-256"].forEach((label) =>
      headRow.append(el("th", "", label)),
    );
    head.append(headRow);
    table.append(head);
    const body = el("tbody");
    DATA.requests.forEach((item, index) => {
      const row = el("tr");
      [
        String(index + 1),
        item.method,
        item.path,
        String(item.status),
        `${fmt(item.elapsed_ms, 1)} ms`,
        String(item.body_bytes),
        shortDigest(item.body_sha256, 20),
      ].forEach((value, cellIndex) =>
        row.append(el("td", cellIndex >= 3 ? "mono" : "", value)),
      );
      body.append(row);
    });
    table.append(body);

    $("reproduce-commands").textContent =
      "PYTHONPATH=src:. python3 -m lab.build_evidence\n" +
      "PYTHONPATH=src:. python3 -m lab.selfcheck\n" +
      "PYTHONPATH=src:. python3 tools/check_shot_index.py\n" +
      "PYTHONPATH=src:. python3 tools/check_contact_sheet.py\n" +
      "PYTHONPATH=src:. python3 -m compileall -q src tools lab";
  }
  TAB_INITS["step-audit"] = initAudit;

  /* ---------------- boot ---------------- */

  if (!DATA) {
    document.body.textContent = "缺少 data.js：先运行 lab.build_evidence 生成实验数据。";
    return;
  }
  showTab("step-frames");
})();
